export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function createFlight(level='calm'){return {x:level==='calm'?-95:-150,y:700,vx:9,vy:-25,angle:0.8,omega:0,fuel:100,time:0,throttle:0,status:'ready',level,trail:[]};}
export function guidance(s){const desiredVx=clamp(-s.x*.075,-16,16);const desiredAngle=clamp((desiredVx-s.vx)*.055,-.38,.38);const turn=clamp((desiredAngle-s.angle)*5-s.omega*3,-1,1);const desiredVy=-clamp(s.y*.075,1.5,36);const acceleration=9.81+(desiredVy-s.vy)*1.8;return {turn,throttle:clamp(acceleration/(24*Math.max(.5,Math.cos(s.angle))),0,1)};}
export function step(s,input,dt){if(s.status!=='flying')return s;s.time+=dt;s.throttle=s.fuel>0?clamp(input.throttle,0,1):0;s.fuel=Math.max(0,s.fuel-s.throttle*2.2*dt);s.omega+=(input.turn*1.9-s.omega*1.6)*dt;s.angle+=s.omega*dt;const wind=s.level==='gusts'?Math.sin(s.time*.7)*1.5+Math.sin(s.time*2.1)*.5:0;s.vx+=(Math.sin(s.angle)*24*s.throttle+wind-s.vx*.012)*dt;s.vy+=(Math.cos(s.angle)*24*s.throttle-9.81)*dt;s.x+=s.vx*dt;s.y+=s.vy*dt;if(s.y<=0){s.y=0;s.status=Math.abs(s.x)<24&&Math.abs(s.vx)<4&&Math.abs(s.vy)<5&&Math.abs(s.angle)<.15?'landed':'crashed';s.throttle=0;}if(Math.abs(s.x)>1800||s.y>2600){s.status='lost';s.throttle=0;}return s;}
